package com.example.shelflife;
public class CategoryChecks {static int count;static void eq(String expected,String name,String categories){String actual=CategorySuggestions.suggest(name,categories,"");if(!expected.equals(actual))throw new AssertionError(name+" / "+actual);if(!actual.isEmpty()&&!java.util.Arrays.asList(CategorySuggestions.DEFAULTS).contains(actual))throw new AssertionError("Unknown category created");count++;}public static void main(String[] args){eq("Canned Goods","Mega Sardines in Tomato Sauce","Fish preserves");eq("Canned Goods","Tuna","Canned fish");eq("Beverages","Orange juice","Fruit juices");eq("Dairy and Eggs","Fresh milk","Dairy");eq("Snacks and Biscuits","Biscuits","Biscuits");eq("Condiments and Spices","Soy sauce","Condiments");eq("Bread and Bakery","Sliced bread","Breads");eq("Frozen Foods","Frozen peas","Frozen vegetables");eq("","Mystery item","Unrecognized catalog taxonomy");eq("","Fresh sardines","");if(CategorySuggestions.inventoryVisible("Household Products")||CategorySuggestions.inventoryVisible("Toiletries")||!CategorySuggestions.inventoryVisible("Canned Goods"))throw new AssertionError("Inventory filters");count++;eq("Snacks and Biscuits","Milk biscuits","Biscuits");eq("Beverages","Milk tea","Beverages");eq("Instant Noodles","Lucky Me Pancit Canton","");eq("Laundry Products","Surf Detergent","");eq("Laundry Products","New Brand","Laundry detergents");eq("Canned Goods","Century Tuna","");eq("Snacks and Biscuits","Piattos","");eq("Dairy and Eggs","Bear Brand Milk","");eq("Beverages","Coca-Cola","");eq("Bread and Bakery","Gardenia Bread","");eq("","Unknown cleaner","Household Products");eq("","Shampoo","Toiletries");
 java.util.List<String> options=CategorySuggestions.choices(java.util.Arrays.asList("  Pet   Food ","pet food","PET FOOD","  Household   Products ","Others"));if(java.util.Collections.frequency(options,"Pet Food")!=1||options.contains("Others")||options.contains("Household Products"))throw new AssertionError("Dedup / blocked categories");count++;
 System.out.println("PASSED: "+count+" category suggestion/filter checks");}}
